package cybershield.model;

import java.util.List;

/**
 * DashboardStats — Aggregates live statistical metrics for both
 * the Web dashboard and the Java Swing desktop dashboard.
 *
 * Review 2 Enhancements:
 * - Total detected threats.
 * - Active security alerts count.
 * - Automatically generated incidents count.
 * - Latest security alert for dedicated alert banner.
 * - Recent security alert history feed.
 */
public class DashboardStats {
    private int totalIncidents;
    private int openIncidents;
    private int criticalIncidents;
    private int unauthorizedEvents;

    // Review 2: Automated Threat Metrics
    private int totalDetectedThreats;
    private int activeSecurityAlerts;
    private int autoGeneratedIncidents;
    private SecurityAlert latestAlert;
    private List<SecurityAlert> recentAlerts;

    // Review 3: Defensive Countermeasures & Security Triage Metrics
    private int activeBlockedIps;
    private int lockedAccounts;
    private int successfulThreatResponses;
    private int failedThreatResponses;
    private int highCriticalIncidents;

    private List<Incident> recentIncidents;
    private List<ActivityLog> recentActivities;

    public DashboardStats() {
    }

    public DashboardStats(int totalIncidents, int openIncidents, int criticalIncidents, int unauthorizedEvents,
                          List<Incident> recentIncidents, List<ActivityLog> recentActivities) {
        this.totalIncidents = totalIncidents;
        this.openIncidents = openIncidents;
        this.criticalIncidents = criticalIncidents;
        this.unauthorizedEvents = unauthorizedEvents;
        this.recentIncidents = recentIncidents;
        this.recentActivities = recentActivities;
    }

    public DashboardStats(int totalIncidents, int openIncidents, int criticalIncidents, int unauthorizedEvents,
                          int totalDetectedThreats, int activeSecurityAlerts, int autoGeneratedIncidents,
                          SecurityAlert latestAlert, List<SecurityAlert> recentAlerts,
                          List<Incident> recentIncidents, List<ActivityLog> recentActivities) {
        this.totalIncidents = totalIncidents;
        this.openIncidents = openIncidents;
        this.criticalIncidents = criticalIncidents;
        this.unauthorizedEvents = unauthorizedEvents;
        this.totalDetectedThreats = totalDetectedThreats;
        this.activeSecurityAlerts = activeSecurityAlerts;
        this.autoGeneratedIncidents = autoGeneratedIncidents;
        this.latestAlert = latestAlert;
        this.recentAlerts = recentAlerts;
        this.recentIncidents = recentIncidents;
        this.recentActivities = recentActivities;
    }

    public int getTotalIncidents() {
        return totalIncidents;
    }

    public void setTotalIncidents(int totalIncidents) {
        this.totalIncidents = totalIncidents;
    }

    public int getOpenIncidents() {
        return openIncidents;
    }

    public void setOpenIncidents(int openIncidents) {
        this.openIncidents = openIncidents;
    }

    public int getCriticalIncidents() {
        return criticalIncidents;
    }

    public void setCriticalIncidents(int criticalIncidents) {
        this.criticalIncidents = criticalIncidents;
    }

    public int getUnauthorizedEvents() {
        return unauthorizedEvents;
    }

    public void setUnauthorizedEvents(int unauthorizedEvents) {
        this.unauthorizedEvents = unauthorizedEvents;
    }

    public int getTotalDetectedThreats() {
        return totalDetectedThreats;
    }

    public void setTotalDetectedThreats(int totalDetectedThreats) {
        this.totalDetectedThreats = totalDetectedThreats;
    }

    public int getActiveSecurityAlerts() {
        return activeSecurityAlerts;
    }

    public void setActiveSecurityAlerts(int activeSecurityAlerts) {
        this.activeSecurityAlerts = activeSecurityAlerts;
    }

    public int getAutoGeneratedIncidents() {
        return autoGeneratedIncidents;
    }

    public void setAutoGeneratedIncidents(int autoGeneratedIncidents) {
        this.autoGeneratedIncidents = autoGeneratedIncidents;
    }

    public SecurityAlert getLatestAlert() {
        return latestAlert;
    }

    public void setLatestAlert(SecurityAlert latestAlert) {
        this.latestAlert = latestAlert;
    }

    public List<SecurityAlert> getRecentAlerts() {
        return recentAlerts;
    }

    public void setRecentAlerts(List<SecurityAlert> recentAlerts) {
        this.recentAlerts = recentAlerts;
    }

    public List<Incident> getRecentIncidents() {
        return recentIncidents;
    }

    public void setRecentIncidents(List<Incident> recentIncidents) {
        this.recentIncidents = recentIncidents;
    }

    public List<ActivityLog> getRecentActivities() {
        return recentActivities;
    }

    public void setRecentActivities(List<ActivityLog> recentActivities) {
        this.recentActivities = recentActivities;
    }

    public int getActiveBlockedIps() {
        return activeBlockedIps;
    }

    public void setActiveBlockedIps(int activeBlockedIps) {
        this.activeBlockedIps = activeBlockedIps;
    }

    public int getLockedAccounts() {
        return lockedAccounts;
    }

    public void setLockedAccounts(int lockedAccounts) {
        this.lockedAccounts = lockedAccounts;
    }

    public int getSuccessfulThreatResponses() {
        return successfulThreatResponses;
    }

    public void setSuccessfulThreatResponses(int successfulThreatResponses) {
        this.successfulThreatResponses = successfulThreatResponses;
    }

    public int getFailedThreatResponses() {
        return failedThreatResponses;
    }

    public void setFailedThreatResponses(int failedThreatResponses) {
        this.failedThreatResponses = failedThreatResponses;
    }

    public int getHighCriticalIncidents() {
        return highCriticalIncidents;
    }

    public void setHighCriticalIncidents(int highCriticalIncidents) {
        this.highCriticalIncidents = highCriticalIncidents;
    }
}
